 tune=[("Bonk knockback","3 U/s"),("Charged bonk","×2.5"),("Sleep max","6"),("Sleep time","3 s"),("Round","60 s cap")],
 unit="animal height = 1U (panda, sloth, frog, goat)",
 assets=["Animals: 1U, round bodies, stubby arms, matching pyjamas with stripes","Pillows: 0.6U soft rounded rectangles","Bed: 10U mattress with puffy quilt bumps (play area)","Toy box: 2U rounded wooden crate","Milk mug and cookie: 0.3U, rounded"],
 bands=["lavender wall with soft night-light glow","blurred posters and shelves","headboard and blanket folds"],
